with matched_keys as (select status, id from orders intersect select status, id from orders where store_id in (21, 26)), reconciled as (select s.* from orders s inner join matched_keys k on s.status = k.status and s.id = k.id) select case when shipping_fee >= 42 then 'LARGE' else 'SMALL' end as shipping_fee_tier, max(discount) as max_discount, count(case when channel = 'store' then 1 end) as store_count, corr(shipping_fee, discount) as corr_shipping_fee_discount, round(sum(discount) / nullif(count(case when status = 'PENDING' then 1 end), 0), 2) as discount_per_pending, count(*) as event_count from reconciled group by 1 order by event_count nulls last;
